  position: absolute;
  width: 56vw;
  height: 56vw;
  left: 47%;
  top: 42%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(196, 159, 98, 0.075), transparent 65%);
  filter: blur(30px);
}

.backdrop-grid {
